INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 21, 'theory', 'Quiz: oVirt networks');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 0, 'What happens to a host if a required network of the cluster is not working on it?', '["The host keeps working unchanged", "The host is removed from the cluster", "The host moves to the NonOperational state", "The host is rebooted automatically"]', 2, 'A required network is needed on all hosts of the cluster. If it is missing, the engine moves the host to NonOperational and the machines leave it. An optional network does not behave that way.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 1, 'Which bond mode requires a configured LACP group on the switch ports?', '["802.3ad (mode 4)", "active-backup (mode 1)", "balance-tlb (mode 5)", "balance-alb (mode 6)"]', 0, 'Mode 4 negotiates with the switch over LACP, so an aggregation group is needed there. Modes 1, 5 and 6 work without switch support.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 2, 'What does VDSM do if, after setupNetworks with the connectivity check, the engine could not reach the host?', '["Keeps the new configuration", "Reboots the host", "Removes the host from the cluster", "Restores the previous configuration"]', 3, 'That is exactly what the check is for: if the engine cannot reach the host within the timeout after applying, the previous configuration is restored.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 3, 'Where are port mirroring, the network filter and the rate limit of a virtual NIC set?', '["In the virtual disk properties", "In the vNIC profile", "In the storage cluster settings", "By hand in the libvirt configuration on each host"]', 1, 'The vNIC profile lives at the network level and holds such settings; a machine gets them by connecting to the network through the profile.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 4, 'Which tunnel protocol do hosts use for OVN overlay networks in oVirt?', '["GRE over VLAN", "IPsec ESP", "Geneve", "A VLAN trunk only, no tunnels"]', 2, 'Hosts running ovn-controller are joined by Geneve tunnels over UDP. The tunnel adds headers, so the MTU of the logical network is smaller than the physical one.');
